    return scopes.scopes
def nested(value=Security(inner, scopes=['inner'])):
    return value
def sibling(scopes: SecurityScopes, token: str = Depends(scheme)):
    return scopes.scopes
def parent(a=Depends(nested), b=Security(sibling, scopes=['sibling']), scopes: SecurityScopes = None):
    return {'inner': a, 'sibling': b, 'outer': scopes.scopes}
@app.get('/')
def endpoint(result=Security(parent, scopes=['outer'])):
    return result
response = TestClient(app).get('/', headers={'Authorization': 'Bearer token'})
assert response.status_code == 200, response.text
assert response.json() == {'inner': ['outer', 'inner'], 'sibling': ['outer', 'sibling'], 'outer': ['outer']}, response.json()
requirements = app.openapi()['paths']['/']['get']['security']
assert {'OAuth2PasswordBearer': ['outer', 'inner']} in requirements, requirements
assert {'OAuth2PasswordBearer': ['outer', 'sibling']} in requirements, requirements
print('hierarchical and sibling scopes verified')
